import nbformat as nbf
from pathlib import Path

OUT = Path(__file__).with_name("gemini_non_table_probe.ipynb")

CELLS = [('markdown', '# Gemini Non-Table Probe - Burnaby R1\n\nThis notebook tests Gemini on **non-table sentence/clause evidence only**.\n\nIt is designed to be quota-friendly: evidence is grouped by source block, so Burnaby normally uses about 3 calls rather than one call per sentence.'), ('code', "import json\nimport os\nimport re\nimport time\nfrom pathlib import Path\n\nimport pandas as pd\nimport requests\nfrom tqdm.auto import tqdm\n\ndef locate_prototype_dir():\n    cwd = Path.cwd()\n    for d in [cwd, *cwd.parents]:\n        candidate = d / 'code' / 'prototype_pipeline'\n        if (candidate / 'prototype_rule_extraction_pipeline.ipynb').exists():\n            return candidate.resolve()\n        if (d / 'prototype_rule_extraction_pipeline.ipynb').exists():\n            return d.resolve()\n    return cwd.resolve()\n\nPROTOTYPE_DIR = locate_prototype_dir()\nos.chdir(PROTOTYPE_DIR)\n\nimport sys\nimport importlib\nif str(PROTOTYPE_DIR) not in sys.path:\n    sys.path.insert(0, str(PROTOTYPE_DIR))\nimport prototype_target_aware_helpers as helpers\nimportlib.reload(helpers)\nfrom prototype_target_aware_helpers import *\n\nprint('PROTOTYPE_DIR:', PROTOTYPE_DIR)"), ('markdown', '## Config'), ('code', "TARGET_CITY = 'burnaby'\nRUN_ID = f'prototype_{TARGET_CITY}_rule_pipeline'\nRULE_DIR = PROTOTYPE_DIR / 'outputs' / TARGET_CITY / RUN_ID / '03_rules'\nPROBE_DIR = PROTOTYPE_DIR / 'outputs' / TARGET_CITY / RUN_ID / '06_gemini_non_table_probe'\nPROBE_DIR.mkdir(parents=True, exist_ok=True)\n\nGEMINI_MODEL = 'gemini-2.5-flash-lite'\nGEMINI_API_KEY = os.getenv('GEMINI_API_KEY', '')\n# GEMINI_API_KEY = 'PASTE_KEY_HERE'\n\nREQUEST_TIMEOUT = 180\nTEMPERATURE = 0.0\nMAX_OUTPUT_TOKENS = 10000\n\n# Efficient modes:\n# - 'by_block': one call per source block, best default for clause context.\n# - 'single': one call for all non-table evidence; cheapest but may be long.\nNON_TABLE_CALL_MODE = 'by_block'\nMAX_EVIDENCE_PER_CALL = 30\n\n# Free-tier stability controls. Gemini may return 429 even with only a few calls.\n# Cooldown + exponential backoff is cheaper than increasing chunk size blindly.\nGEMINI_CALL_COOLDOWN_SECONDS = 0\nGEMINI_MAX_RETRIES = 4\nGEMINI_RETRY_BASE_SECONDS = 45\n\nprint('RULE_DIR:', RULE_DIR)\nprint('PROBE_DIR:', PROBE_DIR)\nprint('Gemini model:', GEMINI_MODEL)\nprint('API key set:', bool(GEMINI_API_KEY))\nprint('Cooldown seconds:', GEMINI_CALL_COOLDOWN_SECONDS)\nprint('Max retries:', GEMINI_MAX_RETRIES)"), ('markdown', '## Load Non-Table Evidence'), ('code', "evidence_units_path = RULE_DIR / 'evidence_units.json'\nevidence_units = json.loads(evidence_units_path.read_text(encoding='utf-8'))\n\nADMIT = {'rule_bearing', 'ambiguous_rule_like'}\nnon_table_evidence = [\n    ev for ev in evidence_units\n    if ev.get('evidence_type') not in {'table_row', 'table_cell'}\n    and ev.get('pre_class') in ADMIT\n]\n\nprint('All evidence units:', len(evidence_units))\nprint('Non-table admitted evidence:', len(non_table_evidence))\ndisplay(pd.DataFrame(non_table_evidence)[['source_block_id','evidence_id','evidence_type','pre_class','text']].head(40))"), ('markdown', '## Build Efficient Evidence Chunks'), ('code', "def compact_evidence(ev):\n    return {\n        'evidence_id': ev.get('evidence_id'),\n        'source_block_id': ev.get('source_block_id'),\n        'evidence_type': ev.get('evidence_type'),\n        'pre_class': ev.get('pre_class'),\n        'section': ev.get('section') or ev.get('bylaw_section'),\n        'heading_path': ev.get('heading_path'),\n        'text': ev.get('text'),\n    }\n\ndef chunk_by_block(evidence):\n    chunks = []\n    by_block = {}\n    for ev in evidence:\n        by_block.setdefault(ev.get('source_block_id', 'unknown'), []).append(ev)\n    for block_id, evs in by_block.items():\n        for i in range(0, len(evs), MAX_EVIDENCE_PER_CALL):\n            chunks.append((f'{block_id}__chunk_{i // MAX_EVIDENCE_PER_CALL + 1:02d}', evs[i:i + MAX_EVIDENCE_PER_CALL]))\n    return chunks\n\nif NON_TABLE_CALL_MODE == 'single':\n    evidence_chunks = [('all_non_table', non_table_evidence)]\nelse:\n    evidence_chunks = chunk_by_block(non_table_evidence)\n\nprint('Gemini non-table calls:', len(evidence_chunks))\nfor chunk_id, evs in evidence_chunks:\n    print(f'  {chunk_id}: evidence={len(evs)}')"), ('markdown', '## Prompt'), ('code', 'def build_non_table_prompt(chunk_id, evidence_list):\n    compact = json.dumps([compact_evidence(ev) for ev in evidence_list], ensure_ascii=False)\n    return f\'\'\'Extract zoning rules from non-table legal text. Return JSON only.\n\nTarget context: Burnaby R1 / Rear Principal Building, but generic rules for dwelling units, buildings, lots, yards, access, fire safety, parking, and setbacks are relevant.\n\nImportant extraction policy:\n- Extract rules from sentence and clause evidence only. No table rows are included.\n- Do NOT reject a clause just because the subject is inherited from a previous sentence or heading.\n- If a clause contains a numeric value, permission, prohibition, required action, or exception, extract it and put inherited context in condition.\n- Split multi-value clauses into atomic rules.\n- Keep discretionary/exception words such as may, subject to, provided that, except in condition/exception. Do not drop the rule.\n- Every rule must cite exactly one evidence_id from the inventory.\n- Value must appear in the cited evidence text.\n\nReturn this exact JSON shape:\n{{\n  "chunk_id": "{chunk_id}",\n  "rules": [\n    {{\n      "evidence_id": "...",\n      "rule_key": "...",\n      "rule_object": "...",\n      "constraint_type": "min/max/required/permitted/not_permitted/exception/other",\n      "subject": "...",\n      "operator": "<= / >= / =",\n      "value": "...",\n      "unit": "...",\n      "condition": "...",\n      "exception": null,\n      "relevance_category": "direct/indirect/generic_applicable/definition_or_reference/ambiguous"\n    }}\n  ],\n  "skipped_evidence": [{{"evidence_id": "...", "reason": "no_rule/context_only/unrelated/duplicate"}}]\n}}\n\nEvidence inventory:\n{compact}\n\'\'\'\n\nprint(build_non_table_prompt(evidence_chunks[0][0], evidence_chunks[0][1])[:3000])'), ('markdown', '## Gemini API Call'), ('code', "def call_gemini_once(prompt):\n    if not GEMINI_API_KEY:\n        raise RuntimeError('GEMINI_API_KEY is not set. Set env var or paste it in the config cell.')\n    url = f'https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent'\n    payload = {\n        'contents': [{'role': 'user', 'parts': [{'text': prompt}]}],\n        'generationConfig': {\n            'temperature': TEMPERATURE,\n            'maxOutputTokens': MAX_OUTPUT_TOKENS,\n            'responseMimeType': 'application/json',\n        },\n    }\n    resp = requests.post(url, params={'key': GEMINI_API_KEY}, json=payload, timeout=REQUEST_TIMEOUT)\n    resp.raise_for_status()\n    data = resp.json()\n    parts = data.get('candidates', [{}])[0].get('content', {}).get('parts', [])\n    return ''.join(p.get('text', '') for p in parts), data\n\n\ndef call_gemini_with_retry(prompt):\n    last_error = None\n    for attempt in range(GEMINI_MAX_RETRIES + 1):\n        if attempt > 0:\n            sleep_s = GEMINI_RETRY_BASE_SECONDS * (2 ** (attempt - 1))\n            print(f'Gemini retry {attempt}/{GEMINI_MAX_RETRIES}; sleeping {sleep_s}s')\n            time.sleep(sleep_s)\n        try:\n            return call_gemini_once(prompt)\n        except requests.HTTPError as exc:\n            status = getattr(exc.response, 'status_code', None)\n            last_error = exc\n            if status not in {429, 500, 502, 503, 504} or attempt >= GEMINI_MAX_RETRIES:\n                raise\n        except (requests.Timeout, requests.ConnectionError) as exc:\n            last_error = exc\n            if attempt >= GEMINI_MAX_RETRIES:\n                raise\n    raise last_error\n"), ('markdown', '## Run Non-Table Probe'), ('code', "probe_logs = []\nraw_rules = []\nskipped_rows = []\nparse_failures = []\n\nfor chunk_index, (chunk_id, evs) in enumerate(tqdm(evidence_chunks, desc='Gemini non-table calls'), start=1):\n    if chunk_index > 1 and GEMINI_CALL_COOLDOWN_SECONDS > 0:\n        print(f'Cooling down {GEMINI_CALL_COOLDOWN_SECONDS}s before {chunk_id}')\n        time.sleep(GEMINI_CALL_COOLDOWN_SECONDS)\n    prompt = build_non_table_prompt(chunk_id, evs)\n    raw_text = ''\n    call_error = None\n    parse_status = 'not_run'\n    parse_error = None\n    rules = []\n    skipped = []\n    started = time.time()\n    try:\n        raw_text, raw_api = call_gemini_with_retry(prompt)\n        obj, err = parse_llm_json_response(raw_text)\n        if obj is None:\n            parse_status = 'parse_error'\n            parse_error = f'{type(err).__name__}: {err}' if err else 'parse_error'\n        else:\n            rules = [r for r in obj.get('rules', []) if isinstance(r, dict)] if isinstance(obj, dict) else []\n            skipped = [r for r in obj.get('skipped_evidence', []) if isinstance(r, dict)] if isinstance(obj, dict) else []\n            parse_status = 'success_json'\n            for r in rules:\n                r['chunk_id'] = chunk_id\n            raw_rules.extend(rules)\n            skipped_rows.extend(skipped)\n    except Exception as e:\n        call_error = f'{type(e).__name__}: {e}'\n    seconds = time.time() - started\n    if parse_status != 'success_json' and raw_text:\n        parse_failures.append({'chunk_id': chunk_id, 'parse_status': parse_status, 'parse_error': parse_error, 'raw_excerpt': raw_text[:2000]})\n    probe_logs.append({\n        'chunk_id': chunk_id,\n        'evidence_count': len(evs),\n        'rule_count': len(rules),\n        'skipped_count': len(skipped),\n        'parse_status': parse_status,\n        'parse_error': parse_error,\n        'call_error': call_error,\n        'seconds': seconds,\n        'raw_response': raw_text,\n    })\n\nlogs_df = pd.DataFrame(probe_logs)\nraw_rules_df = pd.DataFrame(raw_rules)\nskipped_df = pd.DataFrame(skipped_rows)\nfailures_df = pd.DataFrame(parse_failures)\n\ndisplay(logs_df[['chunk_id','evidence_count','rule_count','skipped_count','parse_status','call_error','seconds']])\ndisplay(raw_rules_df.head(80))\nprint('Total raw rules:', len(raw_rules_df))"), ('markdown', '## Deterministic Postprocess'), ('code', "evidence_lookup = {ev.get('evidence_id'): ev for ev in non_table_evidence}\n\ndef clean(value):\n    if value is None:\n        return ''\n    try:\n        if pd.isna(value):\n            return ''\n    except Exception:\n        pass\n    return str(value).strip()\n\ndef norm(value):\n    return re.sub(r'\\s+', ' ', clean(value).lower()).strip()\n\ndef normalize_unit_local(unit):\n    u = norm(unit)\n    if u in {'%', 'percent'}:\n        return 'percent'\n    if u in {'m', 'metre', 'metres', 'meter', 'meters'}:\n        return 'm'\n    if u in {'sq. m', 'sq m', 'm2', 'square metre', 'square metres'}:\n        return 'sq. m'\n    if 'storey' in u or 'story' in u:\n        return 'storeys'\n    return u\n\ndef normalize_non_table_key(rule):\n    text = norm(' '.join(clean(rule.get(k)) for k in ['rule_key','rule_object','subject','condition']))\n    ev_text = norm(evidence_lookup.get(rule.get('evidence_id'), {}).get('text', ''))\n    hay = text + ' ' + ev_text\n    if 'sprinkler' in hay:\n        return 'required_automatic_sprinkler_system'\n    if 'fire access corridor' in hay and ('width' in hay or '1.0' in hay):\n        return 'min_fire_access_corridor_width'\n    if 'clear' in hay and 'height' in hay:\n        return 'min_clear_height'\n    if 'panhandle' in hay and 'width' in hay:\n        return 'min_panhandle_width'\n    if 'walkway' in hay and 'spaced' in hay:\n        return 'max_pedestrian_walkway_spacing'\n    if 'walkway' in hay and 'wide' in hay:\n        return 'min_pedestrian_walkway_width'\n    if 'main entrance' in hay:\n        return 'required_main_entrance_orientation'\n    if 'floor area' in hay:\n        return 'min_floor_area'\n    if 'lot coverage' in hay:\n        return 'max_lot_coverage_exception'\n    if 'impervious' in hay:\n        return 'max_impervious_surface_exception'\n    if 'street yard' in hay and ('setback' in hay or '2.0' in hay):\n        return 'min_street_yard_setback_exception'\n    if 'parking' in hay and 'not required' in hay:\n        return 'not_required_off_street_parking'\n    if 'parking' in hay:\n        return 'parking_location_permission'\n    if 'separation' in hay and '6.0' in hay:\n        return 'min_separation_between_front_and_rear_principals'\n    if 'separation' in hay and '2.4' in hay:\n        return 'min_separation_between_other_principals'\n    return re.sub(r'[^a-z0-9]+', '_', clean(rule.get('rule_key'))).strip('_') or 'unknown_rule'\n\nprocessed = []\nfor _, row in raw_rules_df.iterrows():\n    rule = row.to_dict()\n    ev = evidence_lookup.get(rule.get('evidence_id'), {})\n    rule['evidence_text'] = ev.get('text', '')\n    rule['normalized_rule_key'] = normalize_non_table_key(rule)\n    rule['unit'] = normalize_unit_local(rule.get('unit'))\n    rule['value_visible'] = value_visible_in_evidence(rule, ev.get('text', ''))\n    rule['final_action'] = 'REVIEW' if any(w in norm(ev.get('text', '')) for w in ['may', 'subject to', 'provided that', 'except']) else 'ACCEPT'\n    processed.append(rule)\n\nprocessed_df = pd.DataFrame(processed)\nif not processed_df.empty:\n    processed_df['dedup_key'] = processed_df.apply(lambda r: '|'.join(norm(r.get(c)) for c in ['evidence_id','normalized_rule_key','operator','value','unit','condition','exception']), axis=1)\n    deduped_df = processed_df.drop_duplicates('dedup_key').reset_index(drop=True)\nelse:\n    deduped_df = processed_df.copy()\n\nprint('Processed rules:', len(processed_df))\nprint('Deduped rules:', len(deduped_df))\nif not deduped_df.empty:\n    display(deduped_df[['evidence_id','normalized_rule_key','operator','value','unit','condition','exception','value_visible','final_action','evidence_text']].head(100))"), ('markdown', '## Save Outputs'), ('code', "logs_path = PROBE_DIR / 'gemini_non_table_probe_logs.csv'\nrules_path = PROBE_DIR / 'gemini_non_table_rules_raw.csv'\nprocessed_path = PROBE_DIR / 'gemini_non_table_rules_postprocessed.csv'\ndeduped_path = PROBE_DIR / 'gemini_non_table_rules_postprocessed_deduped.csv'\nskipped_path = PROBE_DIR / 'gemini_non_table_skipped.csv'\nfailures_path = PROBE_DIR / 'gemini_non_table_parse_failures.csv'\nsummary_path = PROBE_DIR / 'gemini_non_table_summary.md'\n\nlogs_df.to_csv(logs_path, index=False, encoding='utf-8-sig')\nraw_rules_df.to_csv(rules_path, index=False, encoding='utf-8-sig')\nprocessed_df.to_csv(processed_path, index=False, encoding='utf-8-sig')\ndeduped_df.to_csv(deduped_path, index=False, encoding='utf-8-sig')\nskipped_df.to_csv(skipped_path, index=False, encoding='utf-8-sig')\nfailures_df.to_csv(failures_path, index=False, encoding='utf-8-sig')\n\nsummary = [\n    '# Gemini Non-Table Summary', '',\n    f'evidence_units: {len(non_table_evidence)}',\n    f'api_calls: {len(evidence_chunks)}',\n    f'raw_rules: {len(raw_rules_df)}',\n    f'processed_rules: {len(processed_df)}',\n    f'deduped_rules: {len(deduped_df)}',\n    f'parse_failures: {len(failures_df)}',\n    '', '## Rule Counts By Key',\n    deduped_df['normalized_rule_key'].value_counts().sort_index().to_string() if not deduped_df.empty else '(none)',\n]\nsummary_path.write_text('\\n'.join(summary), encoding='utf-8')\n\nprint('Saved:', PROBE_DIR)\nprint('\\n' + summary_path.read_text(encoding='utf-8'))")]

